def candidate(q, k, v):
    b,h,s,d=q.shape
    block=128
    qt=q.reshape(b,h,s//block,block,d).transpose(2,0,1,3,4)
    def step(args):
        i,x=args
        z=jnp.einsum('bhqd,bhkd->bhqk',x,k)*jnp.float32(d**-0.5)
        mask=(i*block+jnp.arange(block))[:,None]>=jnp.arange(s)[None,:]
        z=jnp.where(mask,z,-jnp.inf)
        p=jax.nn.softmax(z,axis=-1)
        return jnp.einsum('bhqk,bhkd->bhqd',p,v)
    out=jax.lax.map(step,(jnp.arange(s//block),qt))
    return out.transpose(1,2,0,3,4).reshape(q.shape)

def candidate(q,k,v):
