def candidate(q,k,v):
    b,h,s,d=q.shape
    group=2
    qs=q.reshape(b*h//group,group,s,d)
    ks=k.reshape(b*h//group,group,s,d)
    vs=v.reshape(b*h//group,group,s,d)
    mask=jnp.arange(s)[:,None]>=jnp.arange(s)[None,:]
    def step(args):
        x,y,w=args
        z=jnp.einsum('hqd,hkd->hqk',x,y)*jnp.float32(d**-0.5)
        p=jax.nn.softmax(jnp.where(mask,z,-jnp.inf),axis=-1)
        return jnp.einsum('hqk,hkd->hqd',p,w)
    return jax.lax.map(step,(qs,ks,vs)).reshape(q.shape)

def candidate(q,k,v):
    b,h,s,d=q.shape
    qs=q.reshape(b*h,s,d)
    ks=k.reshape(b*h,s,d)
    vs=v.reshape(b*h,s,d)
    mask=jnp.arange(s)[:,None]>=jnp.arange(s)[None,:]
    def step(args):
        x,y,w=args
        z=jnp.dot(x,y.T)*jnp.float32(d**-0.5)
        p=jax.nn.softmax(jnp.where(mask,z,-jnp.inf),axis=-1)
        return jnp.dot(p,w)
    return jax.lax.map(step,(qs,ks,vs)).reshape(q.shape)

def candidate(q,k,v):
    b,h,s,d=q.shape
    group=4
    qs=q.reshape(b*h//group,group,s,d)
    ks=k.reshape(b*h//group,group,s,d)
    vs=v.reshape(b*h//group,group,s,d)
    def step(args):
        x,y,w=args
        out=[]
        for start in range(0,s,512):
            end=min(start+512,s)
            z=jnp.einsum('hqd,hkd->hqk',x[:,start:end,:],y[:,:end,:])*jnp.float32(d**-0.5)
            mask=jnp.arange(start,end)[:,None]>=jnp.arange(end)[None,:]
            p=jax.nn.softmax(jnp.where(mask,z,-jnp.inf),axis=-1)
            out.append(jnp.einsum('hqk,hkd->hqd',p,w[:,:end,:]))
        return jnp.concatenate(out,axis=1)
    return jax.lax.map(step,(qs,ks,vs)).reshape(q.shape)

