import jax.experimental.pallas as pl
import jax.experimental.pallas.triton as plt

def candidate(x):
    n = x.shape[1]
    def kernel(x_ref, y_ref):
        v = pl.load(x_ref, (0, jnp.arange(n)))
        e = jnp.exp(v - jnp.max(v, axis=0))
        y = e / jnp.sum(e, axis=0)
